def file_hash(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def source_manifest():
    names=[p for p in sorted(ROOT.rglob('*')) if p.is_file() and ('src' in p.relative_to(ROOT).parts or 'tests' in p.relative_to(ROOT).parts or p.parent==ROOT) and '__pycache__' not in p.parts and p.name!='P7A_SOURCE_REVISION.json' and p.suffix in {'.py','.json','.md'}]
    return {str(p.relative_to(ROOT)):file_hash(p) for p in names}

