def validate(c,base,protocol_hash,decision_hash):
    validate_p6(base)
    if digest(base)!=BASE_SHA or c['parent_p6_canonical_sha256']!=BASE_SHA:raise ContractError('Not the sealed P6 base')
    if c['authorization']!={k:False for k in FLAGS}:raise ContractError('No scientific/execution/public approval')
    if c['schema_version']!='p7a-pilot-design-candidate-0.1' or c['state']!='UNSIGNED_OWNER_DESIGN_REVIEW':raise ContractError('Unsigned versioned design')
    source=c['source']['p7a_implementation_content_sha']
    if re.fullmatch('[0-9a-f]{40}',source) is None:raise ContractError('Exact source SHA')
    expected=make_candidate(source,base,protocol_hash,decision_hash)
    if c!=expected:raise ContractError('Missing/altered/contradictory draft,source,task catalog,protocol or decision identity; create a new reviewed version')
    p=c['pilot']
    if p['decisions']!=p['pairs']*p['episodes_per_unit']*p['steps_per_episode']*p['policies'] or p['model_call_ceiling']!=512*p['decisions']:raise ContractError('Budget algebra')
    if any(c['holdout'][k] for k in ['authorized','paths','seed_manifest','regime_values']):raise ContractError('No holdout')
    return True


def validate_decisions(record):
    if record['explicit_approved_scientific_decisions'] or any(record[k] is not False for k in ['scientific_protocol_approved','pilot_execution_authorized','heldout_execution_authorized','publication_authorized']):raise ContractError('No explicit owner approval verified')
    if record['owner_signature'] is not None or record['signed_at'] is not None:raise ContractError('Unsigned record only; no invented signature')
    if not record['decisions'] or any(r['owner_approved'] is not False or r['owner_response'] is not None or r['approval_evidence'] is not None or r['status']!='PENDING_OWNER_REVIEW' for r in record['decisions']):raise ContractError('Pending owner decisions cannot masquerade as approval')
    return True
